#!/usr/bin/env node
/**
 * Build the Malibu blog from Markdown sources.
 *
 * Source of truth:  blog/posts/<slug>.md   (frontmatter + Markdown body)
 * Generated:        blog/<slug>/index.html (one per post, a Vite input via glob)
 *                   blog/index.html         (post listing)
 *                   public/sitemap.xml      (served at /sitemap.xml)
 *                   public/blog/feed.xml    (served at /blog/feed.xml)
 *
 * Adding a post = add one Markdown file and run `npm run blog:build`.
 * Never edit the generated files or vite.config.js by hand.
 *
 * SECURITY: post bodies may be authored by an unattended agent, so all
 * untrusted values are treated as hostile: bodies are sanitized against an
 * allowlist, JSON-LD is escaped for <script> context, and every XML sink is
 * entity-escaped. One malformed post is skipped, never fatal to the build.
 */
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { marked } from 'marked';
import sanitizeHtml from 'sanitize-html';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const postsDir = join(root, 'blog', 'posts');
const blogDir = join(root, 'blog');
const publicDir = join(root, 'public');

const SITE = 'https://malibu.tech';
const DEFAULT_AUTHOR = 'The Malibu team';
const DEFAULT_HERO = '/images/brand/blog-hero-macbook-sunset-mesh.jpg';
const RESERVED_SLUGS = new Set(['posts', 'index', 'feed']);
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const BANNER_MARK = 'GENERATED by scripts/build-blog.mjs';
const BANNER = (slug) =>
  `<!-- ${BANNER_MARK} from blog/posts/${slug}.md — do not edit directly. -->`;

// ---------------------------------------------------------------------------
// Escaping — one helper per output context. Never mix them up.
// ---------------------------------------------------------------------------

const escAttr = (s = '') =>
  String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const escText = (s = '') =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// XML text/attribute content — escape the full entity set.
const escXml = (s = '') =>
  String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');

// JSON embedded in <script type="application/ld+json"> — neutralize the byte
// sequences that could close the tag or break out of the block.
const jsonForScript = (obj) =>
  JSON.stringify(obj, null, 2)
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/&/g, '\\u0026')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');

const slugify = (s = '') =>
  String(s)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

function formatDate(str) {
  const d = new Date(str);
  if (Number.isNaN(d.getTime())) return '';
  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
}

// ---------------------------------------------------------------------------
// Markdown → sanitized HTML, with heading anchors + a table of contents.
// ---------------------------------------------------------------------------

marked.setOptions({ gfm: true, breaks: false });
marked.use({
  renderer: {
    heading({ tokens, depth, text }) {
      const inner = this.parser.parseInline(tokens);
      const id = slugify(text);
      return `<h${depth}${id ? ` id="${escAttr(id)}"` : ''}>${inner}</h${depth}>\n`;
    },
  },
});

const SANITIZE = {
  allowedTags: [
    'p', 'a', 'ul', 'ol', 'li', 'strong', 'em', 'b', 'i', 'code', 'pre',
    'blockquote', 'hr', 'br', 'h2', 'h3', 'h4', 'img', 'span',
  ],
  allowedAttributes: {
    '*': ['id'],
    a: ['href', 'title', 'target', 'rel'],
    img: ['src', 'alt', 'title', 'width', 'height', 'loading'],
  },
  allowedSchemes: ['http', 'https', 'mailto'],
  allowedSchemesByTag: { img: ['http', 'https', 'data'] },
  transformTags: {
    // Add rel=noopener while MERGING (keep href/title); javascript: hrefs are
    // dropped by the scheme allowlist above.
    a: sanitizeHtml.simpleTransform('a', { rel: 'noopener' }, true),
  },
};

function renderBody(markdown) {
  const dirty = marked.parse(markdown);
  return sanitizeHtml(dirty, SANITIZE);
}

function tableOfContents(markdown) {
  const headings = marked
    .lexer(markdown)
    .filter((t) => t.type === 'heading' && t.depth === 2)
    .map((t) => ({ text: t.text, id: slugify(t.text) }))
    .filter((h) => h.id);
  return headings;
}

// ---------------------------------------------------------------------------
// Frontmatter — minimal, controlled format. Values are raw strings/booleans;
// list normalization happens per-field in loadPost so a bare `keywords: a, b`
// can never crash the build.
// ---------------------------------------------------------------------------

function parseFrontmatter(raw) {
  const m = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!m) return { data: {}, body: raw };
  const data = {};
  for (const line of m[1].split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = line.indexOf(':');
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    let val = line.slice(idx + 1).trim();
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }
    if (val === 'true' || val === 'false') data[key] = val === 'true';
    else data[key] = val;
  }
  return { data, body: m[2] };
}

function toList(val) {
  if (Array.isArray(val)) return val;
  if (val == null || val === '') return [];
  return String(val)
    .replace(/^\[|\]$/g, '')
    .split(',')
    .map((s) => s.trim().replace(/^["']|["']$/g, ''))
    .filter(Boolean);
}

// Optional structured-data fields carry a one-line JSON value. Malformed JSON is
// warned + ignored (the FAQ/HowTo is simply omitted) rather than dropping the post.
function parseJsonField(raw, label) {
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (err) {
    console.warn(`build-blog: ignoring malformed "${label}" JSON — ${err.message}`);
    return null;
  }
}

// Require actual strings — never String()-coerce, or `{"a":42}` ships "42" and
// `{"q":{...}}` ships "[object Object]" as visible + indexed FAQ content.
const str = (v) => (typeof v === 'string' ? v.trim() : '');

function normalizeFaq(v) {
  if (!Array.isArray(v)) return [];
  return v
    .map((it) => ({ q: str(it?.q), a: str(it?.a) }))
    .filter((it) => it.q && it.a);
}

function normalizeHowto(v) {
  if (!v) return null;
  const rawSteps = Array.isArray(v) ? v : Array.isArray(v.steps) ? v.steps : [];
  const steps = rawSteps
    .map((s) => (typeof s === 'string' ? { name: '', text: str(s) } : { name: str(s?.name), text: str(s?.text) || str(s?.name) }))
    .filter((s) => s.text);
  if (!steps.length) return null;
  return {
    name: Array.isArray(v) ? '' : str(v.name),
    totalTime: Array.isArray(v) ? '' : str(v.totalTime),
    steps,
  };
}

function loadPosts() {
  if (!existsSync(postsDir)) return [];
  const posts = [];
  for (const file of readdirSync(postsDir)) {
    if (!file.endsWith('.md')) continue;
    try {
      const raw = readFileSync(join(postsDir, file), 'utf8');
      const { data, body } = parseFrontmatter(raw);
      const slug = slugify(data.slug || basename(file, '.md'));
      if (!slug) throw new Error('empty slug');
      if (RESERVED_SLUGS.has(slug)) throw new Error(`reserved slug "${slug}"`);
      if (!data.title || !data.date) throw new Error('missing required frontmatter (title, date)');
      if (Number.isNaN(new Date(data.date).getTime())) {
        throw new Error(`unparseable date "${data.date}"`);
      }
      // Fail SAFE on draft: any truthy-looking value keeps the post unpublished,
      // so a stray `draft: true # note` (string) never leaks live. Only an
      // explicit falsey value publishes.
      const draftVal = data.draft;
      const isDraft =
        draftVal === true ||
        (typeof draftVal === 'string' && /^\s*(true|yes|on|1|draft)\b/i.test(draftVal));
      if (isDraft) continue;

      const canonical = data.canonical || `${SITE}/blog/${slug}/`;
      const rawOgImage = data.ogImage || data.heroImage || DEFAULT_HERO;
      const ogImage = rawOgImage.startsWith('/') ? `${SITE}${rawOgImage}` : rawOgImage;
      const words = body.trim().split(/\s+/).filter(Boolean).length;

      // Warn when structured-data frontmatter is present but yields nothing
      // usable (e.g. a bare array of the wrong shape) — silent omission hides bugs.
      const faqRaw = parseJsonField(data.faq, 'faq');
      const faq = normalizeFaq(faqRaw);
      if (faqRaw && !faq.length) console.warn(`build-blog: ${file} — "faq" had no usable {q,a} pairs; omitting.`);
      const howtoRaw = parseJsonField(data.howto, 'howto');
      const howto = normalizeHowto(howtoRaw);
      if (howtoRaw && !howto) console.warn(`build-blog: ${file} — "howto" had no usable steps; omitting.`);

      posts.push({
        slug,
        title: data.title,
        headline: data.headline || data.title,
        category: data.category || 'Notes',
        author: data.author || DEFAULT_AUTHOR,
        date: data.date,
        dateModified: data.updated || data.date,
        dateDisplay: formatDate(data.date),
        readingTime: Math.max(1, Math.round(words / 200)),
        description: data.description || data.lede || '',
        ogTitle: data.ogTitle || data.title,
        ogDescription: data.ogDescription || data.description || data.lede || '',
        ogImage,
        isDefaultHero: ogImage.endsWith('blog-hero-macbook-sunset-mesh.jpg'),
        lede: data.lede || '',
        excerpt: data.excerpt || data.lede || data.description || '',
        heroImage: data.heroImage || '',
        heroAlt: data.heroAlt || '',
        keywords: toList(data.keywords),
        canonical,
        faq,
        howto,
        bodyHtml: renderBody(body.trim()),
        toc: tableOfContents(body.trim()),
      });
    } catch (err) {
      console.warn(`build-blog: skipping blog/posts/${file} — ${err.message}`);
    }
  }
  return posts.sort((a, b) => new Date(b.date) - new Date(a.date));
}

