function jsonLd(post) {
  const article = {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: post.title,
    description: post.description,
    image: post.ogImage,
    datePublished: post.date,
    dateModified: post.dateModified,
    author: { '@type': 'Organization', name: post.author, url: SITE },
    publisher: {
      '@type': 'Organization',
      name: 'Malibu AI, Inc.',
      logo: { '@type': 'ImageObject', url: `${SITE}/favicon.png` },
    },
    mainEntityOfPage: { '@type': 'WebPage', '@id': post.canonical },
  };
  if (post.keywords.length) article.keywords = post.keywords.join(', ');
  const breadcrumb = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Malibu', item: `${SITE}/` },
      { '@type': 'ListItem', position: 2, name: 'Blog', item: `${SITE}/blog/` },
      { '@type': 'ListItem', position: 3, name: post.title, item: post.canonical },
    ],
  };
  const blocks = [article, breadcrumb];

  // Opt-in FAQ/HowTo — only emitted when the post supplies matching frontmatter,
  // so structured data never claims content the page doesn't have.
  if (post.faq.length) {
    blocks.push({
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: post.faq.map((f) => ({
        '@type': 'Question',
        name: f.q,
        acceptedAnswer: { '@type': 'Answer', text: f.a },
      })),
    });
  }
  if (post.howto) {
    const howto = {
      '@context': 'https://schema.org',
      '@type': 'HowTo',
      name: post.howto.name || post.title,
      step: post.howto.steps.map((s, i) => ({
        '@type': 'HowToStep',
        position: i + 1,
        ...(s.name ? { name: s.name } : {}),
        text: s.text,
      })),
    };
    if (post.howto.totalTime) howto.totalTime = post.howto.totalTime;
    blocks.push(howto);
  }

  return blocks
    .map((o) => `  <script type="application/ld+json">\n${jsonForScript(o)}\n  </script>`)
    .join('\n');
}

function renderPost(post) {
  const hero = post.heroImage
    ? `      <figure class="post-hero">
        <img src="${escAttr(post.heroImage)}" alt="${escAttr(post.heroAlt)}" width="1280" height="714" loading="eager" fetchpriority="high" />
      </figure>\n`
    : '';
  const keywordsMeta = post.keywords.length
    ? `  <meta name="keywords" content="${escAttr(post.keywords.join(', '))}" />\n`
    : '';
  const ogDims = post.isDefaultHero
    ? `  <meta property="og:image:width" content="1280" />\n  <meta property="og:image:height" content="714" />\n`
    : '';
  const byline = `      <div class="post-byline">
        <span>By <strong>${escText(post.author)}</strong></span>${
          post.dateDisplay ? `\n        <span class="sep">·</span>\n        <span>${escText(post.dateDisplay)}</span>` : ''
        }
        <span class="sep">·</span>
        <span>${post.readingTime} min read</span>
      </div>`;
  // TOC covers body headings plus the generated HowTo/FAQ sections, so the
  // "jump to any section" list doesn't miss them.
  const howtoHeading = post.howto ? post.howto.name || 'Steps' : '';
  const tocEntries = [
    ...post.toc,
    ...(post.howto ? [{ text: howtoHeading, id: 'steps' }] : []),
    ...(post.faq.length ? [{ text: 'Frequently asked questions', id: 'faq' }] : []),
  ];
  const toc =
    tocEntries.length >= 3
      ? `      <nav class="post-toc" aria-label="On this page">
        <div class="post-toc-label">On this page</div>
        <ul>
${tocEntries.map((h) => `          <li><a href="#${escAttr(h.id)}">${escText(h.text)}</a></li>`).join('\n')}
        </ul>
      </nav>\n`
      : '';
  // Render HowTo steps visibly from the same data that feeds the HowTo JSON-LD,
  // so the structured data always describes content that's actually on the page.
  const howtoSection = post.howto
    ? `
      <section class="post-howto" id="steps" aria-labelledby="howto-heading">
        <h2 id="howto-heading">${escText(howtoHeading)}</h2>
        <ol class="howto-steps">
${post.howto.steps
  .map(
    (s) =>
      `          <li>${s.name ? `<strong>${escText(s.name)}.</strong> ` : ''}${escText(s.text)}</li>`,
  )
  .join('\n')}
        </ol>
      </section>\n`
    : '';
  // Render the FAQ visibly from the same data that feeds the FAQPage JSON-LD.
  const faqSection = post.faq.length
    ? `
      <section class="post-faq" id="faq" aria-labelledby="faq-heading">
        <h2 id="faq-heading">Frequently asked questions</h2>
${post.faq
  .map(
    (f) => `        <div class="faq-item">
          <h3 id="${escAttr(slugify(f.q))}">${escText(f.q)}</h3>
          <p>${escText(f.a)}</p>
        </div>`,
  )
  .join('\n')}
      </section>\n`
    : '';
  return `<!doctype html>
<html lang="en">
${BANNER(post.slug)}
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta name="description" content="${escAttr(post.description)}" />
${keywordsMeta}  <link rel="canonical" href="${escAttr(post.canonical)}" />
  <meta property="og:title" content="${escAttr(post.ogTitle)}" />
  <meta property="og:description" content="${escAttr(post.ogDescription)}" />
  <meta property="og:type" content="article" />
  <meta property="og:url" content="${escAttr(post.canonical)}" />
  <meta property="og:image" content="${escAttr(post.ogImage)}" />
${ogDims}  <meta property="article:published_time" content="${escAttr(post.date)}" />
  <meta name="twitter:card" content="summary_large_image" />
  <meta name="twitter:title" content="${escAttr(post.ogTitle)}" />
  <meta name="twitter:description" content="${escAttr(post.ogDescription)}" />
  <meta name="twitter:image" content="${escAttr(post.ogImage)}" />
  <title>${escText(post.title)} · Malibu</title>
${HEAD_ASSETS}
${jsonLd(post)}
${POST_STYLE}
</head>
<body>

<!-- ============ FLOATING NAV ============ -->
${nav('post-nav-menu')}

<main id="top" style="background: #143A45; color: #FAFBFF; min-height: 100vh;">

  <!-- ============ ARTICLE HEADER ============ -->
  <section style="position: relative; padding: clamp(120px, 18vh, 200px) clamp(20px, 5vw, 80px) clamp(32px, 4vh, 56px);">
    <div aria-hidden="true" style="position: absolute; top: 0; left: 30%; right: 30%; height: 260px; background: radial-gradient(ellipse at top, rgba(247, 107, 87,0.18), transparent 70%); pointer-events: none;"></div>
    <div class="post-wrap" style="position: relative;">
      <a href="/blog/" class="post-back">
        <svg width="10" height="8" viewBox="0 0 14 10" fill="none" aria-hidden="true"><path d="M13 5 H1 M5 1 L1 5 L5 9" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
        Blog
      </a>
      <div class="post-eyebrow">
        <span>${escText(post.category)}</span>
      </div>
      <h1 class="post-title">${escText(post.headline)}</h1>
      <p class="post-lede">${escText(post.lede)}</p>
${byline}
${hero}    </div>
  </section>

  <!-- ============ ARTICLE BODY ============ -->
  <section style="position: relative; padding: 0 clamp(20px, 5vw, 80px) clamp(72px, 10vh, 120px);">
    <div class="post-wrap post-body">

${toc}${post.bodyHtml}
${howtoSection}${faqSection}
      <hr class="post-hr" />

      <div class="post-cta-grid">
        <a href="/host/" class="post-cta">
          <div class="post-cta-label">Own a Mac?</div>
          <div class="post-cta-title">Host a model →</div>
          <div class="post-cta-sub">One command. Zero configuration. Earning from the first request.</div>
        </a>
        <a href="/console/" class="post-cta">
          <div class="post-cta-label">Buy inference?</div>
          <div class="post-cta-title">Open the console →</div>
          <div class="post-cta-sub">Point your OpenAI SDK at Malibu. Nothing else changes.</div>
        </a>
      </div>

    </div>
  </section>

  <!-- ============ FOOTER ============ -->
${footer()}
</main>

<script type="module" src="/src/nav.js"></script>
</body>
</html>
`;
}

// ---------------------------------------------------------------------------
// Index page
// ---------------------------------------------------------------------------

